import { siteConfig } from "@/config/site";

/** True once NEXT_PUBLIC_DISCORD_URL has been set. */
export const discordConfigured = Boolean(siteConfig.discordUrl);

/**
 * Where "Open Discord Ticket" points. Until the Discord invite is configured
 * in `.env.local`, every ticket button routes to /support instead of a dead
 * link, and the support page explains how to reach us.
 */
export const discordHref = siteConfig.discordUrl || "/support";

export const supportEmailConfigured = Boolean(siteConfig.supportEmail);
export const supportEmailHref = siteConfig.supportEmail
  ? `mailto:${siteConfig.supportEmail}`
  : "/support";
