import Link from "next/link";
import { ArrowUpRight, Mail, MessageSquareText } from "lucide-react";
import { Logo } from "@/components/brand/Logo";
import { footerLinks, siteConfig } from "@/config/site";
import {
  discordConfigured,
  discordHref,
  supportEmailConfigured,
  supportEmailHref,
} from "@/lib/links";

function FooterColumn({
  title,
  links,
}: {
  title: string;
  links: readonly { href: string; label: string }[];
}) {
  return (
    <div>
      <h3 className="text-[11px] font-medium uppercase tracking-[0.2em] text-silver-500">
        {title}
      </h3>
      <ul className="mt-4 flex flex-col gap-2.5">
        {links.map((link) => (
          <li key={link.href}>
            <Link
              href={link.href}
              className="text-[13.5px] text-silver-300 transition-colors hover:text-white"
            >
              {link.label}
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}

export function Footer() {
  const year = new Date().getFullYear();

  return (
    <footer className="relative z-1 mt-8 border-t border-white/8 bg-[#06060b]">
      <div
        aria-hidden="true"
        className="absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-violet-400/30 to-transparent"
      />
      <div className="shell py-14 lg:py-16">
        <div className="grid gap-10 lg:grid-cols-[1.4fr_repeat(3,1fr)]">
          <div className="max-w-sm">
            <Logo />
            <p className="mt-4 text-[13.5px] leading-relaxed text-silver-400">
              {siteConfig.longDescription}
            </p>
            <div className="mt-5 flex flex-wrap gap-2">
              <a
                href={discordHref}
                target={discordConfigured ? "_blank" : undefined}
                rel={discordConfigured ? "noopener noreferrer" : undefined}
                className="inline-flex items-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] px-3.5 py-2 text-[13px] text-silver-200 transition hover:border-violet-300/40 hover:bg-white/[0.07] hover:text-white"
              >
                <MessageSquareText className="h-4 w-4" aria-hidden="true" />
                {discordConfigured ? "Discord" : "Discord (not configured)"}
                {discordConfigured ? (
                  <ArrowUpRight className="h-3.5 w-3.5" aria-hidden="true" />
                ) : null}
              </a>
              {supportEmailConfigured ? (
                <a
                  href={supportEmailHref}
                  className="inline-flex items-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] px-3.5 py-2 text-[13px] text-silver-200 transition hover:border-white/25 hover:bg-white/[0.07] hover:text-white"
                >
                  <Mail className="h-4 w-4" aria-hidden="true" />
                  Email
                </a>
              ) : null}
            </div>
          </div>

          <FooterColumn title="Store" links={footerLinks.store} />
          <FooterColumn title="Help" links={footerLinks.help} />
          <FooterColumn title="Legal" links={footerLinks.legal} />
        </div>

        <div className="mt-12 border-t border-white/8 pt-7">
          <p className="max-w-4xl text-[12px] leading-relaxed text-silver-500">
            {siteConfig.disclaimer}
          </p>
          <div className="mt-5 flex flex-col gap-2 text-[12px] text-silver-500 sm:flex-row sm:items-center sm:justify-between">
            <p>
              © {year} {siteConfig.legalName}. All rights reserved.
            </p>
            <p>{siteConfig.tagline}</p>
          </div>
        </div>
      </div>
    </footer>
  );
}
